// Lấy đơn từ body webhook (app An Yên gửi lên)
const order = ($input.first().json.body) || $input.first().json || {};
const vnd = n => (Number(n)||0).toLocaleString('vi-VN') + 'đ';
const lines = [];
lines.push('🧾 ĐƠN MỚI — ' + (order.shop || 'An Yên'));
lines.push('');
(order.items || []).forEach(it => {
  const opt = it.opts ? '  (' + it.opts + ')' : '';
  lines.push('• ' + it.name + ' × ' + it.qty + opt + '  ' + vnd(it.lineTotal));
});
lines.push('—');
lines.push('Tổng: ' + vnd(order.total) + '  (' + (order.count || 0) + ' món)');
const cus = order.customer || {};
if (cus.name || cus.phone) lines.push('Khách: ' + [cus.name, cus.phone].filter(Boolean).join(' · '));
if (order.note) lines.push('Ghi chú: ' + order.note);
const zaloText = lines.join('\n');
const itemsText = (order.items || []).map(i => i.name + (i.opts ? '('+i.opts+')' : '') + ' x' + i.qty).join(', ');
return [{ json: {
  at: order.at || new Date().toISOString(),
  shop: order.shop || 'An Yên',
  customerName: cus.name || '',
  customerPhone: cus.phone || '',
  itemsText: itemsText,
  count: order.count || 0,
  total: order.total || 0,
  note: order.note || '',
  zaloText: zaloText
} }];
